mapper.select:
SELECT E_BILL_ID, E_BILL_NO, BILL_TYPE, BILL_AMOUNT, CURRENCY, DRAWER_NAME, DRAWER_ACCOUNT, DRAWER_BANK, ACCEPTOR_NAME, ACCEPTOR_ACCOUNT, ACCEPTOR_BANK, PAYEE_NAME, PAYEE_ACCOUNT, ISSUE_DATE, MATURITY_DATE, BILL_STATUS, DIGITAL_SIGNATURE, SIGNATURE_STATUS, VERIFICATION_STATUS, ELECTRONIC_STATUS, BILL_PURPOSE, CONTRACT_NUMBER, REMARK, CREATE_TIME, UPDATE_TIME FROM TBL_ELECTRONIC_BILL WHERE DELETE_FLAG = 0
AND E_BILL_NO LIKE CONCAT('%', #{query.billNumber}, '%')
AND BILL_TYPE = #{query.billType}
AND BILL_STATUS = #{query.billStatus}
AND ISSUE_DATE >= #{query.issueDateStart}
AND ISSUE_DATE <= #{query.issueDateEnd}
ORDER BY CREATE_TIME DESC
